Certainly! Below are two Unity C# scripts that simulate a bouncing ball, each fulfilling the given constraints.

### Script 1: Ball Bouncing on a Flat Surface
```csharp
using UnityEngine;

public class BouncingBallFlat : MonoBehaviour
{
    private Vector3 velocity = Vector3.zero;
    private float gravity = -9.81f;
    private float damping = 0.8f;

    void Start()
    {
        velocity = new Vector3(0, 10, 0);
    }

    void Update()
    {
        velocity.y += gravity * Time.deltaTime;
        transform.position += velocity * Time.deltaTime;

        if (transform.position.y <= 0)
        {
            transform.position = new Vector3(transform.position.x, 0, transform.position.z);
            velocity.y = -velocity.y * damping;

            if (Mathf.Abs(velocity.y) < 0.1f)
            {
                velocity = Vector3.zero; // Ball stops moving
            }
        }
    }
}
// Simulation complete: Ball stopped moving.
```

