        this.name = name;
        this.age = age;
        this.gpa = gpa;
    }

    // Method to display information about the student
    public void displayInfo() {
        System.out.println("Name: " + name);
        System.out.println("Age: " + age);
        System.out.println("GPA: " + gpa);
    }

    // Main method to create instances and test the displayInfo method
    public static void main(String[] args) {
        // Create two instances of the Student class
        Student student1 = new Student("Alice", 20, 3.5);
        Student student2 = new Student("Bob", 22, 3.8);

        // Call displayInfo for each instance
        student1.displayInfo();
        System.out.println(); // Print a blank line for separation
        student2.displayInfo();
    }
}
