```csharp
using System;
using System.Windows.Forms;

namespace WinFormsApp
{
    public class MainForm : Form
    {
        private Button myButton; // This is the button control
        private TextBox myTextBox; // This is the textbox control

        public MainForm()
        {
            InitializeComponent();
        }

        private void InitializeComponent()
        {
            // Initialize the button
            myButton = new Button();
            myButton.Text = "Click Me";
            myButton.Location = new System.Drawing.Point(50, 50);
            myButton.Click += new EventHandler(MyButton_Click);

            // Initialize the textbox
            myTextBox = new TextBox();
            myTextBox.Location = new System.Drawing.Point(50, 100);

            // Add controls to the form
            this.Controls.Add(myButton); // Add button to form
            this.Controls.Add(myTextBox); // Add textbox to form

            // Set the form properties
            this.Text = "Simple WinForms Application";
            this.StartPosition = FormStartPosition.CenterScreen;
            this.ClientSize = new System.Drawing.Size(300, 200);
        }

        private void MyButton_Click(object sender, EventArgs e)
        {
            // Display a message box when button is clicked
            MessageBox.Show("WinForms exploration complete!");
        }

        [STAThread]
        static void Main()
        {
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            Application.Run(new MainForm());
        }
    }
}
```

