#include <iostream>
#include <sstream>
#include <ctime>
#include <vector>
#include <string>
#include <openssl/sha.h> // include openssl for sha256 hashing

// function to calculate sha256 hash
std::string calculate_sha256(const std::string& input) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)input.c_str(), input.size(), hash);

    std::stringstream ss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        ss << std::hex << (int)hash[i];
    }
    return ss.str();
}

// class representing a single block in the blockchain
class Block {
public:
    std::string previous_hash;
    std::string data;
    std::string hash;
    long timestamp;
    int nonce;

    // constructor for the block
    Block(std::string previous_hash, std::string data)
        : previous_hash(previous_hash), data(data), nonce(0) {
        timestamp = std::time(nullptr);
        hash = calculate_hash(); // calculate the hash when creating the block
    }

    // function to calculate hash of the block
    std::string calculate_hash() const {
        std::stringstream ss;
        ss << previous_hash << timestamp << data << nonce;
        return calculate_sha256(ss.str());
    }

    // function to perform proof of work
    void mine_block(int difficulty) {
        std::string target(difficulty, '0'); // create a target string with 'difficulty' number of leading zeros
        while (hash.substr(0, difficulty) != target) {
            nonce++;
            hash = calculate_hash(); // recalculate hash with new nonce
        }
        std::cout << "block mined: " << hash << std::endl;
    }
};

// class representing the entire blockchain
class Blockchain {
public:
    std::vector<Block> chain;
    int difficulty;

    // constructor for the blockchain
    Blockchain(int difficulty) : difficulty(difficulty) {
        chain.emplace_back(create_genesis_block()); // create the genesis block
    }

    // function to create the first block in the blockchain
    Block create_genesis_block() {
        return Block("0", "genesis block");
    }

    // function to get the latest block in the chain
    Block get_latest_block() const {
        return chain.back();
    }

    // function to add a new block to the blockchain
    void add_block(Block new_block) {
        new_block.previous_hash = get_latest_block().hash; // set the previous hash of the new block
        new_block.mine_block(difficulty); // perform mining operation
        chain.push_back(new_block); // add the new block to the chain
    }
};

int main() {
    Blockchain blockchain(4); // create a blockchain with a difficulty of 4

    std::cout << "mining block 1..." << std::endl;
    blockchain.add_block(Block(blockchain.get_latest_block().hash, "block 1 data"));

    std::cout << "mining block 2..." << std::endl;
    blockchain.add_block(Block(blockchain.get_latest_block().hash, "block 2 data"));

    std::cout << "mining block 3..." << std::endl;
    blockchain.add_block(Block(blockchain.get_latest_block().hash, "block 3 data"));

    return 0;
}
```

### explanation of the code:

1. **hashing function**: the function `calculate_sha256` takes a string input and returns its sha-256 hash using openssl.

2. **block class**: this class represents a block in the blockchain. each block contains:
   - `previous_hash`: a string storing the hash of the previous block.
   - `data`: a string storing the data of the block.
   - `hash`: the hash of the current block.
   - `timestamp`: the time when the block was created.
   - `nonce`: a number used for the proof of work.

3. **blockchain class**: this class manages the chain of blocks. it contains:
   - `chain`: a vector of `Block` objects representing the blockchain.
   - `difficulty`: an integer representing the difficulty of the proof of work.

4. **main function**: initializes a blockchain with a difficulty of 4 and adds three new blocks with different data, each requiring mining before being added to the chain.

