<<PlanetaryOrbitSimulation>>

import scala.math._

object PlanetaryOrbitSimulation {
  // Gravitational constant in appropriate units
  val G = 6.67430e-11

  // Define the mass of the star and the planet in kilograms
  val massStar = 1.989e30  // Mass of the sun
  val massPlanet = 5.972e24 // Mass of the earth

  // Define initial position and velocity of the planet
  var position = (1.496e11, 0.0, 0.0) // Initial position in meters (1 AU)
  var velocity = (0.0, 29780.0, 0.0)  // Initial velocity in meters per second

  // Define the time step and the total time for one orbit (365.25 days)
  val timeStep = 60.0  // 1 minute in seconds
  val totalTime = 365.25 * 24 * 3600  // One year in seconds

  def main(args: Array[String]): Unit = {
    // Calculate the number of steps needed for one complete orbit
    val numberOfSteps = (totalTime / timeStep).toInt

    // Simulate the orbit over the defined number of steps
    for (step <- 0 to numberOfSteps) {
      // Calculate the gravitational force
      val (fx, fy, fz) = gravitationalForce(position)

      // Update the velocity using the force and time step
      val (vx, vy, vz) = velocity
      velocity = (
        vx + fx / massPlanet * timeStep,
        vy + fy / massPlanet * timeStep,
        vz + fz / massPlanet * timeStep
      )

      // Update the position using the velocity and time step
      val (x, y, z) = position
      position = (
        x + vx * timeStep,
        y + vy * timeStep,
        z + vz * timeStep
      )

      // Output the position of the planet at this time step
      println(f"Time: ${step * timeStep / (24*3600)}%.2f days, Position: (${position._1}%.2f, ${position._2}%.2f, ${position._3}%.2f)")
    }
  }

  // Function to calculate the gravitational force on the planet by the star
  def gravitationalForce(position: (Double, Double, Double)): (Double, Double, Double) = {
    val (x, y, z) = position
    val distance = sqrt(x*x + y*y + z*z)
    val forceMagnitude = G * massStar * massPlanet / (distance * distance)
    (
      -forceMagnitude * x / distance,
      -forceMagnitude * y / distance,
      -forceMagnitude * z / distance
    )
  }
}
```

